const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const moroto = ee.Geometry.Point([34.666, 2.54]);
    const roi = moroto.buffer(40000); // 40 km
    const aug2023Start = '2023-08-01';
    const aug2023End = '2023-09-01';
    const baseStart = '1991-01-01';
    const baseEnd = '2010-12-31';

    // Helper: compute mean and count for an image over ROI.
    async function regionStats(img, scale) {
      const mean = ee.Number(
        img.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: roi,
          scale: scale,
          maxPixels: 1e9
        }).get('NDVI')
      );
      const count = ee.Number(
        img.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: roi,
          scale: scale,
          maxPixels: 1e9
        }).get('NDVI')
      );
      const totalCount = ee.Number(
        ee.Image.constant(1).rename('NDVI').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: roi,
          scale: scale,
          maxPixels: 1e9
        }).get('NDVI')
      );
      const out = {
        mean: null,
        count: null,
        totalCount: null
      };
      try {
        out.mean = await mean.getInfo();
      } catch (e) { out.mean = null; }
      try {
        out.count = await count.getInfo();
      } catch (e) { out.count = null; }
      try {
        out.totalCount = await totalCount.getInfo();
      } catch (e) { out.totalCount = null; }
      return out;
    }

    // Attempt 1: NOAA AVHRR CDR NDVI (monthly)
    async function tryNOAA() {
      const assets = ['NOAA/CDR/AVHRR/NDVI/V5', 'NOAA/CDR/AVHRR/NDVI/V4'];
      for (let a = 0; a < assets.length; a++) {
        try {
          const asset = assets[a];
          // Build collections
          let col2023 = ee.ImageCollection(asset)
            .filterDate(aug2023Start, aug2023End)
            .filter(ee.Filter.calendarRange(8, 8, 'month'))
            .filterBounds(roi)
            .select('NDVI')
            .map(img => img.multiply(0.0001).rename('NDVI')
              .updateMask(img.neq(-9999))); // basic fill mask
          let baseCol = ee.ImageCollection(asset)
            .filterDate(baseStart, baseEnd)
            .filter(ee.Filter.calendarRange(8, 8, 'month'))
            .filterBounds(roi)
            .select('NDVI')
            .map(img => img.multiply(0.0001).rename('NDVI')
              .updateMask(img.neq(-9999)));

          const n2023 = await col2023.size().getInfo();
          const nBase = await baseCol.size().getInfo();
          if (n2023 === 0 || nBase === 0) continue; // try next asset

          // Mask NDVI outside physical bounds just in case
          col2023 = col2023.map(i => i.updateMask(i.gte(-0.2)).updateMask(i.lte(1)));
          baseCol = baseCol.map(i => i.updateMask(i.gte(-0.2)).updateMask(i.lte(1)));

          const img2023 = col2023.mean();
          const imgBase = baseCol.mean();
          const scale = 5000;

          const s2023 = await regionStats(img2023, scale);
          const sBase = await regionStats(imgBase, scale);

          console.log(`Dataset: ${asset} (monthly)`);
          console.log(`Aug 2023 Images: ${n2023}`);
          console.log(`Aug 1991-2010 Images: ${nBase}`);

          if (!s2023.count || !sBase.count) {
            console.log('Valid Pixels (2023): 0');
            console.log('Valid Pixels (Baseline): 0');
            console.log('C2');
            return {done: true};
          }
          const vpc2023 = s2023.totalCount ? (100.0 * s2023.count / s2023.totalCount) : null;
          const vpcBase = sBase.totalCount ? (100.0 * sBase.count / sBase.totalCount) : null;

          console.log(`Valid Pixels (2023): ${s2023.count}${vpc2023 != null ? ` (${vpc2023.toFixed(1)}%)` : ''}`);
          console.log(`Valid Pixels (Baseline): ${sBase.count}${vpcBase != null ? ` (${vpcBase.toFixed(1)}%)` : ''}`);

          if (s2023.count === 0 || sBase.count === 0) {
            console.log('C2');
            return {done: true};
          }
          if (s2023.mean == null || sBase.mean == null || !isFinite(s2023.mean) || !isFinite(sBase.mean)) {
            console.log('C3');
            return {done: true};
          }
          if (s2023.mean < -1 || s2023.mean > 1 || sBase.mean < -1 || sBase.mean > 1) {
            console.log('C3');
            return {done: true};
          }

          const diff = s2023.mean - sBase.mean;
          console.log(`Mean NDVI (Aug 2023): ${s2023.mean.toFixed(4)}`);
          console.log(`Mean NDVI (Aug 1991-2010): ${sBase.mean.toFixed(4)}`);
          console.log(`Difference (2023 - baseline): ${diff.toFixed(4)}`);

          const isLower = s2023.mean < sBase.mean;
          console.log(isLower ? 'A' : 'B');
          return {done: true};
        } catch (e) {
          // Try next asset
        }
      }
      return {done: false};
    }

    // Attempt 2: Landsat surface reflectance (fallback)
    async function tryLandsat() {
      function scaleSR(img) {
        const scaled = img.select('SR_B.*').multiply(0.0000275).add(-0.2);
        return img.addBands(scaled, null, true);
      }
      function maskL2Clouds(img) {
        const qa = img.select('QA_PIXEL');
        const cloud = qa.bitwiseAnd(1 << 3).neq(0);
        const cloudShadow = qa.bitwiseAnd(1 << 4).neq(0);
        const snow = qa.bitwiseAnd(1 << 5).neq(0);
        const dilated = qa.bitwiseAnd(1 << 1).neq(0);
        const cirrus = qa.bitwiseAnd(1 << 2).neq(0);
        const radsat = img.select('QA_RADSAT').gt(0);
        const mask = cloud.or(cloudShadow).or(snow).or(dilated).or(cirrus).or(radsat).not();
        return img.updateMask(mask);
      }
      function toNDVI(img, red, nir) {
        const ndvi = img.normalizedDifference([nir, red]).rename('NDVI');
        return ndvi.updateMask(ndvi.gte(-1)).updateMask(ndvi.lte(1));
      }
      function prep(col, red, nir) {
        return col.map(scaleSR).map(maskL2Clouds).map(function(img) {
          return toNDVI(img, red, nir).copyProperties(img, img.propertyNames());
        });
      }

      const l5 = prep(ee.ImageCollection('LANDSAT/LT05/C02/T1_L2'), 'SR_B3', 'SR_B4');
      const l7 = prep(ee.ImageCollection('LANDSAT/LE07/C02/T1_L2'), 'SR_B3', 'SR_B4');
      const l8 = prep(ee.ImageCollection('LANDSAT/LC08/C02/T1_L2'), 'SR_B4', 'SR_B5');
      const l9 = prep(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'), 'SR_B4', 'SR_B5');

      const augFilter = ee.Filter.calendarRange(8, 8, 'month');

      const col2023 = l8.merge(l9).filterDate(aug2023Start, aug2023End).filter(augFilter).filterBounds(roi);
      const n2023 = await col2023.size().getInfo();

      const years = ee.List.sequence(1991, 2010);
      const baseCol = ee.ImageCollection(
        years.map(function(y) {
          y = ee.Number(y);
          const start = ee.Date.fromYMD(y, 8, 1);
          const end = start.advance(1, 'month');
          const perYear = l5.merge(l7).filterDate(start, end).filter(augFilter).filterBounds(roi);
          return ee.Image(perYear.median()).set('year', y);
        })
      );
      const nBaseYears = await baseCol.size().getInfo();

      console.log('Dataset: Landsat SR L2 (Aug composites)');

      console.log(`Aug 2023 Images: ${n2023}`);
      console.log(`Aug 1991-2010 Yearly composites: ${nBaseYears}`);

      if (n2023 === 0 || nBaseYears === 0) {
        console.log('C1');
        return {done: true};
      }

      const img2023 = ee.Image(col2023.median());
      const imgBase = ee.Image(baseCol.mean()); // mean across yearly composites

      const scale = 1000;
      const s2023 = await regionStats(img2023, scale);
      const sBase = await regionStats(imgBase, scale);

      if (!s2023.count || !sBase.count || s2023.count === 0 || sBase.count === 0) {
        console.log(`Valid Pixels (2023): ${s2023.count || 0}`);
        console.log(`Valid Pixels (Baseline): ${sBase.count || 0}`);
        console.log('C2');
        return {done: true};
      }

      const vpc2023 = s2023.totalCount ? (100.0 * s2023.count / s2023.totalCount) : null;
      const vpcBase = sBase.totalCount ? (100.0 * sBase.count / sBase.totalCount) : null;

      console.log(`Valid Pixels (2023): ${s2023.count}${vpc2023 != null ? ` (${vpc2023.toFixed(1)}%)` : ''}`);
      console.log(`Valid Pixels (Baseline): ${sBase.count}${vpcBase != null ? ` (${vpcBase.toFixed(1)}%)` : ''}`);

      if (s2023.mean == null || sBase.mean == null || !isFinite(s2023.mean) || !isFinite(sBase.mean)) {
        console.log('C3');
        return {done: true};
      }
      if (s2023.mean < -1 || s2023.mean > 1 || sBase.mean < -1 || sBase.mean > 1) {
        console.log('C3');
        return {done: true};
      }

      const diff = s2023.mean - sBase.mean;
      console.log(`Mean NDVI (Aug 2023): ${s2023.mean.toFixed(4)}`);
      console.log(`Mean NDVI (Aug 1991-2010): ${sBase.mean.toFixed(4)}`);
      console.log(`Difference (2023 - baseline): ${diff.toFixed(4)}`);

      const isLower = s2023.mean < sBase.mean;
      console.log(isLower ? 'A' : 'B');
      return {done: true};
    }

    const noaaResult = await tryNOAA();
    if (!noaaResult.done) {
      await tryLandsat();
    }
  } catch (e) {
    // If anything unexpected happens, signal a method/data issue.
    try { console.log('D'); } catch(_) {}
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
